      tokens: { 'pr-31': [{ leg: 'dev', at: '2026-10-03T07:00:00Z',
        prompt: 0, completion: 0, cache_read: 2000000, total: 0,
        model: 'm' }] }
    });
    assert.equal(st.lanes.pr_created[0].tokens[0].cost, 1,
      '2M cache reads @ $0.5/Mtok');
  });
});

